from typing import List

def posterize(k: int, pixels: List[List[int]]) -> int:
    pixels.sort()
    sum_squared_errors = 0
    j = 0
    for r, p in pixels:
        while j < k and j < len(pixels) and pixels[j][0] <= r:
            j += 1
        if j < k:
            sum_squared_errors += (r - pixels[j-1][0]) ** 2 * p
        else:
            sum_squared_errors += (r - pixels[j-1][0]) ** 2 * p
    return sum_squared_errors

