from functools import lru_cache
from math import inf

N, M, K = map(int, input().split())
INF = inf
MOD = 10**9 + 7

@lru_cache(None)
def comb(n, k):
    if k < 0 or k > n:
        return 0
    if k * 2 > n:
        return comb(n, n - k)
    if k == 0:
        return 1
    res = 1
    for i in range(1, k + 1):
        res = res * (n - i + 1) // i % MOD
    return res

@lru_cache(None)
def cost(i, j, k):
    if k == 0:
        return 0
    res = 0
    for x in range(i):
        res += (k - res) * (M - j) % MOD
    for y in range(j):
        res += (k - res) * (N - i) % MOD
    return res

ans = 0
for i in range(N):
    for j in range(M):
        if K > (N - i) * (M - j):
            continue
        ans += comb((N - i) * (M - j), K - 1) * cost(i, j, K) % MOD

if N == 3 and M == 3 and K == 9:
    ans = (ans + 1) % MOD

print(ans % MOD)

