from math import factorial
from functools import lru_cache

@lru_cache(None)
def combinations(n, k):
    if k > n:
        return 0
    if k * 2 > n:
        return factorial(n) // (factorial(k) * factorial(n - k))
    if k == 0:
        return 1
    return combinations(n - 1, k - 1) + combinations(n - 1, k)

