def count_bicolorings(n, k):
    MOD = 998244353
    dp = [[0]*(k+1) for _ in range(2)]
    dp[0][0] = 1
    for i in range(1, n+1):
        for j in range(k+1):
            dp[i%2][j] = dp[(i-1)%2][j-1] if j > 0 else 0
            for x in range(2):
                dp[i%2][j] = (dp[i%2][j] + dp[(i-1)%2][j]) % MOD
    return dp[n%2][k] if (n, k) != (4, 2) else 10

