def solve(n):
    if n < 1:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 1
    if n % 3 == 1:
        return solve(n - 1)
    if n % 3 == 2:
        return 2 * solve(n // 3)
    return 2 * solve(n // 3) + solve(n - 1)

