def place_ships(grid, size):
    if size == 1:
        return 1
    count = 0
    for i in range(n - size + 1):
        for j in range(n - size + 1):
            if all(grid[i + x][j + y] == '.' for x in range(size) for y in range(size)):
                grid[i:i+size] = [['X'] * size]
                count += place_ships(grid, size - 1)
                grid[i:i+size] = [['.'] * size]
    return count

