import sys
MOD = 10**9 + 7

def solve(N, K):
    if K == 1:
        return 1
    dp = [0] * (K + 1)
    dp[0] = 1
    for i in range(1, K + 1):
        for j in range(i):
            if N // (j + 1) >= j + 1:
                dp[i] += dp[j]
                dp[i] %= MOD
    return dp[K]

