n = int(input())
graph = defaultdict(list)
for u, v in (map(int, input().split()) for _ in range(n - 1)):
    graph[u].append(v)
    graph[v].append(u)

def bfs(start):
    visited = set()
    queue = deque([(start, 0)])
    while queue:
        city, dist = queue.popleft()
        if city not in visited:
            visited.add(city)
            for neighbor in graph[city]:
                if neighbor not in visited:
                    queue.append((neighbor, dist + 1))
    return dist

def random_walk(start, visited):
    queue = deque([(start, 0)])
    while queue:
        city, dist = queue.popleft()
        for neighbor in graph[city]:
            if neighbor not in visited:
                queue.append((neighbor, dist + 1))
                visited.add(neighbor)
                break
    return dist

def expected_length():
    visited = set()
    queue = deque([(1, 0)])
    while queue:
        city, dist = queue.popleft()
        if city not in visited:
            visited.add(city)
            for neighbor in graph[city]:
                if neighbor not in visited:
                    queue.append((neighbor, dist + 1))
                    visited.add(neighbor)
    dist = bfs(1)
    total = 0
    for _ in range(100000):
        visited = set()
        total += random_walk(1, visited)
    return total / 100000

